  for(var i=0;i<P.length;i++){ if(P[i][0].test(k)) return k.replace(P[i][0],P[i][1][I]); }
  var m=k.match(/^Portfolio · Updated on (\d+) (\w+) (\d{4})$/); if(m) return (L==='fr'?'Portfolio · Mis à jour le ':'Portfolio · Bijgewerkt op ')+m[1]+' '+(MON[L][m[2]]||m[2])+' '+m[3];
