  var doEl=function(e){ if(SKIP[e.nodeName]||(e.closest&&e.closest('[data-noi18n]'))) return; for(var i=0;i<AT.length;i++){ var a=e.getAttribute&&e.getAttribute(AT[i]); if(a){ var t=tr(a); if(t!==a) e.setAttribute(AT[i],t); } } };
  var walk=function(root){ if(root.nodeType===3) return doText(root); if(root.nodeType!==1&&root.nodeType!==9&&root.nodeType!==11) return; if(root.nodeType===1) doEl(root);
    var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT), n; while(n=w.nextNode()){ if(n.nodeType===3) doText(n); else doEl(n); } };
